import 'brace';
import 'brace/mode/css';
import 'brace/mode/html';
import 'brace/theme/eclipse';

import {
	AfterViewInit,
	ChangeDetectorRef,
	Component,
	ElementRef,
	forwardRef,
	Input,
	ViewChild
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { AceComponent } from 'ngx-ace-wrapper';

@Component({
    selector: 'espd-ace-reactive',
    template: '<ace [(value)]="value" [mode]="mode" theme="eclipse" [disabled]="disabled" />',
    styles: [`:host {
				display: block;
			}`],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => AceReactiveComponent),
            multi: true
        }
    ],
    standalone: false
})
export class AceReactiveComponent implements ControlValueAccessor, AfterViewInit {

	@Input()
	public mode: 'css' | 'html' = 'html';

	private _value!: string;
	private _disabled: boolean = false;
	private formIsDisabled: boolean = false;

	@Input()
	public labelledBy?: string;

	@ViewChild(AceComponent)
	public editor!: AceComponent;

	constructor(private changeDetector: ChangeDetectorRef, private elementRef: ElementRef) { }

	public ngAfterViewInit(): void {
		if (this.labelledBy) {
			const textarea: HTMLTextAreaElement = (<HTMLElement>this.elementRef.nativeElement).querySelector('textarea')!;
			textarea.setAttribute('aria-labelledby', this.labelledBy);
		}
		if (this.mode === 'html') {
			this.filterUnwantedDoctypeError();
		}
	}

	get value(): string {
		return this._value;
	}

	@Input()
	set value(val: string) {
		this._value = val;
		this.onChange(val);
		this.onTouched();
		this.changeDetector.detectChanges();
	}

	get disabled(): boolean {
		return this._disabled || this.formIsDisabled;
	}

	@Input()
	set disabled(value: boolean) {
		this._disabled = value;
	}

	public onChange: any = () => { /* do nothing */ };
	public onTouched: any = () => { /* do nothing */ };

	public writeValue(value: string): void {
		if (value) {
			this.value = value;
		}
	}

	public registerOnChange(fn: any): void {
		this.onChange = fn;
	}

	public registerOnTouched(fn: any): void {
		this.onTouched = fn;
	}

	public setDisabledState(isDisabled: boolean): void {
		this.formIsDisabled = isDisabled;
	}

	private filterUnwantedDoctypeError() {
		const session = this.editor.directiveRef!.ace()!.getSession();
		session.on("changeAnnotation", function () {
			const annotations = session.getAnnotations() || [];
			const len = annotations.length;
			let i = annotations.length;

			while (i--) {
				if (/doctype first\. Expected/.test(annotations[i].text) || /Unexpected End of file\. Expected/.test(annotations[i].text)) {
					annotations.splice(i, 1);
				}
			}
			if (len > annotations.length) {
				session.setAnnotations(annotations);
			}
		});
	}
}