import { Component, HostBinding, Input, TemplateRef, ViewChild, forwardRef, inject } from '@angular/core';
import { EspdAbstractSizeableInputDirective, espdAbstractInputComponentInjectionToken } from 'espd-common/forms/api';
import { MessageConfig } from 'espd-common/i18n';
import { ModalService } from 'espd-common/modal';

export interface CodeEditorAction {
	icon?: string,
	action: () => any,
	srMessage: MessageConfig | string
}

@Component({
	selector: 'espd-code-editor',
	templateUrl: './code-editor.component.html',
	styleUrls: ['./code-editor.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => CodeEditorComponent) }],
	standalone: false
})
export class CodeEditorComponent extends EspdAbstractSizeableInputDirective {

	@Input()
	public mode: 'css' | 'html' = 'html';

	@Input()
	public buttonConfig?: CodeEditorAction;

	@Input()
	public supportedTags: string[] = ['a', 'b', 'blockquote', 'br', 'caption',
		'cite', 'code', 'col', 'colgroup', 'dd', 'div', 'dl', 'dt', 'em', 'footer',
		'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'i', 'img', 'li', 'ol', 'p', 'pre', 'q',
		'small', 'span', 'strike', 'strong', 'sub', 'sup',
		'table', 'tbody', 'td', 'tfoot', 'th', 'thead', 'tr', 'u', 'ul'];

	@HostBinding('class')
	public class = 'form-group d-flex flex-column';

	@ViewChild('tagsModalTemplate')
	public modalTemplateRef!: TemplateRef<any>;

	private modalService = inject(ModalService);

	public showMarkupDialog(): void {
		this.modalService.show({ key: 'common.code.supportedTags' }, this.modalTemplateRef, [{ content: { key: 'common.close' }, value: true, secondary: true }]);
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}